# UHRS embedded installer — NO download of zip required.
# From PowerShell INSIDE your backend folder:
#
#   cd "C:\Users\Henry Okojie\Documents\vettedme-backend"
#   Invoke-WebRequest -Uri "https://raw.githubusercontent.com/chatnrent-jpg/C-FutureMathics.ai-/cursor/uhrs-dropin-sync-8175/tools/vettedme-uhrs-dropin/APPLY-UHRS-EMBEDDED.ps1" -OutFile .\APPLY-UHRS-EMBEDDED.ps1
#   powershell -ExecutionPolicy Bypass -File .\APPLY-UHRS-EMBEDDED.ps1
#   npx tsx watch src/index.ts
#
# Then verify: curl.exe -i http://localhost:8080/api/rlhf/uhrs/status  → must be 401

param(
  [string]$Dest = (Get-Location).Path
)
$ErrorActionPreference = "Stop"
Set-Location $Dest

if (-not (Test-Path "src\index.ts")) {
  throw "Not a vettedme-backend folder (src\index.ts missing). cd into Documents\vettedme-backend first."
}

function Write-B64File([string]$RelPath, [string]$B64) {
  $full = Join-Path $Dest $RelPath
  $dir = Split-Path $full -Parent
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  $bytes = [Convert]::FromBase64String(($B64 -replace "\s",""))
  [IO.File]::WriteAllBytes($full, $bytes)
  Write-Host "Wrote $RelPath ($($bytes.Length) bytes)"
}

Write-Host "=== UHRS embed apply -> $Dest ==="

