"@


$routes = Get-Content "src\modules\rlhf-core-rubric\routes.ts" -Raw
if ($routes -notmatch 'uhrs/status') { throw "routes.ts missing uhrs/status after write" }
if (-not (Test-Path "src\modules\rlhf-core-rubric\uhrsService.ts")) { throw "uhrsService.ts missing" }
if (-not (Test-Path "src\modules\rlhf-core-rubric\uhrsController.ts")) { throw "uhrsController.ts missing" }
Write-Host "OK: UHRS route files present"

Write-Host "Running prisma generate + db push..."
npx prisma generate
npx prisma db push

Write-Host "Killing listeners on port 8080..."
try {
  $conns = Get-NetTCPConnection -LocalPort 8080 -ErrorAction SilentlyContinue
  foreach ($c in $conns) {
    Write-Host "Stopping PID $($c.OwningProcess)"
    Stop-Process -Id $c.OwningProcess -Force -ErrorAction SilentlyContinue
  }
} catch {}
# fallback via netstat
netstat -ano | Select-String ":8080\s" | ForEach-Object {
  $parts = ($_ -split "\s+") | Where-Object { $_ -ne "" }
  $pid = $parts[-1]
  if ($pid -match '^\d+$' -and $pid -ne '0') {
    Write-Host "Stopping PID $pid (netstat)"
    Stop-Process -Id $pid -Force -ErrorAction SilentlyContinue
  }
}
Start-Sleep -Seconds 1

Write-Host ""
Write-Host "=== START API NOW (same folder) ==="
Write-Host "  npx tsx watch src/index.ts"
Write-Host ""
Write-Host "Verify in another window:"
Write-Host "  curl.exe -i http://localhost:8080/api/rlhf/uhrs/status"
Write-Host "Expect: HTTP 401 Unauthorized  (NOT 404)"
Write-Host "Also: curl.exe -s http://localhost:8080/ | findstr uhrs"
